let cycle = global.get('cycle') || 0;
const deg = Math.min(cycle, 100) / 100;
function n(b, noise) { return +(b + (Math.random()-0.5)*2*noise).toFixed(2); }
const fanBlade = n(0.4  + deg * 5.2, 0.12);
const hpcBlade = n(0.3  + deg * 4.1, 0.10);
const lpcBlade = n(0.2  + deg * 3.0, 0.08);
const bearing  = n(0.1  + deg * 3.8, 0.15);
const casing   = n(0.3  + deg * 2.5, 0.09);
const maxVib   = Math.max(fanBlade, hpcBlade, lpcBlade, bearing, casing);
msg.payload    = {fanBlade, hpcBlade, lpcBlade, bearing, casing, maxVib};
return msg;

const v = msg.payload.maxVib;
msg.payload = {time: new Date().toLocaleTimeString(), sensor:'Vibration', value:v.toFixed(2)+' mm/s', level: v > 5 ? 'CRITICAL':'WARNING', color: v > 5 ? '#d50000':'#ff6f00'};
return msg;

const d = msg.payload;
return [
  {payload: d.fanBlade},
  {payload: d.hpcBlade},
  {payload: d.lpcBlade},
  {payload: d.bearing},
  {payload: d.casing}
];

