let cycle = global.get('cycle') || 0;
const deg = Math.min(cycle, 100) / 100;
function n(b, noise) { return +(b + (Math.random()-0.5)*2*noise).toFixed(2); }
const inletP = n(101.3 - deg * 5,   0.5);
const compP  = n(1200  + deg * 150, 10);
const combP  = n(1180  - deg * 200,  8);
const turbP  = n(350   - deg * 60,   5);
msg.payload  = {inletP, compP, combP, turbP};
return msg;

const d = msg.payload;
return [
  {payload: d.inletP},
  {payload: d.compP},
  {payload: d.combP},
  {payload: d.turbP}
];

let cycle = global.get('cycle') || 0;
const deg = Math.min(cycle, 100) / 100;
function n(b, noise) { return +(b + (Math.random()-0.5)*2*noise).toFixed(2); }
msg.payload = {
  fuelFlow: n(2.8 + deg * 0.8,  0.05),
  airFlow:  n(85  - deg * 12,   1.0),
  oilFlow:  n(4.5 - deg * 1.2,  0.08)
};
return msg;

const d = msg.payload;
return [
  {payload: d.fuelFlow},
  {payload: d.airFlow},
  {payload: d.oilFlow}
