let cycle = global.get('cycle') || 0;
const deg = Math.min(cycle, 100) / 100;
const fanRPM  = +(3200 - deg * 500 + (Math.random()-0.5)*40).toFixed(0);
const coreRPM = +(9800 - deg * 1200 + (Math.random()-0.5)*100).toFixed(0);
const torque  = +(150  + deg * 80   + (Math.random()-0.5)*10).toFixed(1);
msg.payload = {fanRPM, coreRPM, torque};
return msg;

const d = msg.payload;
return [
  {payload: d.fanRPM},
  {payload: d.coreRPM},
  {payload: d.torque}
];

let cycle = global.get('cycle') || 0;
let speed  = global.get('deg_speed') || 1;
cycle = Math.min(100, cycle + speed);
global.set('cycle', cycle);
const deg = cycle / 100;
function n(b, noise) { return +(b + (Math.random()-0.5)*2*noise).toFixed(3); }
msg.payload = {
  cycle: Math.round(cycle), deg,
  s1:  n(518.67 + deg*20,    3),   // T2  — fan inlet total temp
  s2:  n(643.02 + deg*30,    5),   // T24 — LPC outlet temp
  s3:  n(1589   + deg*60,   10),   // T30 — HPC outlet temp
  s4:  n(1400   + deg*90,   12),   // T50 — LPT outlet temp
  s5:  n(14.62  + deg*1.5,   0.2), // P2  — inlet pressure
  s6:  n(21.61  - deg*2.0,   0.3), // P15 — bypass duct pressure
  s7:  n(554.36 - deg*50,    5),   // Nf  — physical fan speed
  s8:  n(2388   - deg*120,  20),   // Nc  — physical core speed
  s9:  n(9062   - deg*250,  30),   // Ps30 — HPC static pressure
  s10: n(1.30   + deg*0.35,  0.02),// phi  — fuel-air ratio
  s11: n(47.47  - deg*6,     0.5), // NRf  — corrected fan speed
  s12: n(522    - deg*25,    4),   // NRc  — corrected core speed
  s13: n(2388   - deg*120,  20),   // BPR  — bypass ratio proxy
  s14: n(8138   - deg*180,  30),   // farB — burn fuel-air ratio
  s15: n(9.234  + deg*0.6,   0.1), // htBleed — bleed enthalpy
  s16: n(14.62  + deg*1.0,   0.15),// Nf_dmd — demanded fan speed
  s17: n(23.38  + deg*1.2,   0.3), // PCNfR_dmd — demanded corrected fan speed
  s18: n(100    - deg*20,    1),   // W31 — HPT coolant bleed
  s19: n(38.19  - deg*8,     0.5), // W32 — LPT coolant bleed
  s20: n(9.234  + deg*0.6,   0.1)  // htBleed proxy 2
};
return msg;

const d = msg.payload;
const deg = d.deg;

// Head A: Probabilistic RUL Distribution (mean + CI)
const trueRUL = Math.max(0, 100 - d.cycle);
const predRUL = Math.max(0, trueRUL + (Math.random()-0.5)*8);
const variance = 3 + deg * 15;
const ciLow  = +Math.max(0, predRUL - variance).toFixed(1);
const ciHigh = +(predRUL + variance).toFixed(1);

// Head B: Physics-Violation Risk Score
// Checks degradation monotonicity + thermodynamic bounds (C-MAPSS thresholds)
let physRisk = 0;
if (d.s3 > 1620) physRisk += 0.25;  // HPC outlet overtemp (T30)
if (d.s4 > 1450) physRisk += 0.25;  // LPT overtemp (T50) — turbine inlet limit
if (d.s9 < 8500) physRisk += 0.20;  // HPC pressure drop (Ps30)
if (d.s18 < 88)  physRisk += 0.15;  // HPT coolant bleed depletion (W31)
if (d.s19 < 32)  physRisk += 0.15;  // LPT coolant bleed depletion (W32)
physRisk = Math.min(1.0, physRisk);

// CPC — Counterfactual Physical Consistency Score
const cpc = +(1 - physRisk).toFixed(2);

// Component Health Scores (0-100)
const health = {
  fan:       +Math.max(0, 100 - deg*62 - Math.random()*5).toFixed(0),
  hpc:       +Math.max(0, 100 - deg*72 - Math.random()*6).toFixed(0),
  combustor: +Math.max(0, 100 - deg*55 - Math.random()*4).toFixed(0),
  hpt:       +Math.max(0, 100 - deg*68 - Math.random()*5).toFixed(0),
  lpt:       +Math.max(0, 100 - deg*58 - Math.random()*4).toFixed(0),
  bearing:   +Math.max(0, 100 - deg*85 - Math.random()*6).toFixed(0)
};

// Reliability Gating: ACCEPT / WARN / REJECT
let gate = 'ACCEPT';
if (predRUL <= 40 || physRisk > 0.25) gate = 'WARN';
if (predRUL <= 18 || physRisk > 0.55) gate = 'REJECT';

msg.payload = Object.assign({}, d, {predRUL: +predRUL.toFixed(1), ciLow, ciHigh, physRisk: +physRisk.toFixed(2), cpc, gate, health});
return msg;

const g = msg.payload.gate;
msg.payload = {
  time:   new Date().toLocaleTimeString(),
  sensor: 'RUL Gate',
  value:  'RUL=' + msg.payload.predRUL + ' cyc, Risk=' + (msg.payload.physRisk*100).toFixed(0) + '%',
  level:  g,
  color:  g === 'REJECT' ? '#d50000' : '#ff6f00'
};
return msg;

const d = msg.payload;
const g = d.gate;
const gLabel = g === 'ACCEPT' ? '✅  ACCEPT' : g === 'WARN' ? '⚠️   WARN' : '🔴 REJECT';
return [
  {payload: +d.predRUL.toFixed(1)},
  {payload: gLabel + '\nRUL: ' + d.predRUL + ' cycles\nCI: [' + d.ciLow + ' – ' + d.ciHigh + ']\nPhysics Risk: ' + (d.physRisk*100).toFixed(0) + '%\nCPC: ' + (d.cpc*100).toFixed(0) + '%'},
  {payload: +(d.cpc*100).toFixed(0)},
  {payload: +(d.physRisk*100).toFixed(0)},
  {payload: 'Cycle ' + d.cycle + ' / 100   |   Degradation: ' + (d.deg*100).toFixed(0) + '%'}
];

const h = msg.payload.health;
return [
  {payload: h.fan},
  {payload: h.hpc},
  {payload: h.combustor},
  {payload: h.hpt},
  {payload: h.lpt},
  {payload: h.bearing}
];

const d = msg.payload;
msg.payload = JSON.stringify({
  ts:       new Date().toISOString(),
  cycle:    d.cycle,
  rul:      d.predRUL,
  ci:       [d.ciLow, d.ciHigh],
  gate:     d.gate,
  cpc:      d.cpc,
  physRisk: d.physRisk,
  health:   d.health
});
return msg;

const a = msg.payload;
const icon = (a.level === 'CRITICAL' || a.level === 'REJECT') ? '🔴' : (a.level === 'WARNING' || a.level === 'WARN') ? '⚠️' : 'ℹ️';
msg.payload = icon + ' [' + a.time + ']  ' + a.sensor + ': ' + a.value + '  —  ' + a.level;
return msg;

global.set('cycle', 0);
global.set('anomaly', false);
return null;

let c = global.get('cycle') || 0;
global.set('cycle', Math.min(100, c + 18));
return null;

const on = msg.payload;
global.set('engine_on', on);
if (!on) global.set('cycle', 0);
return null;

const errMsg = (msg.error && msg.error.message) ? msg.error.message : 'Unknown error';
const errSrc  = (msg.error && msg.error.source) ? msg.error.source.name : 'Unknown node';
msg.payload   = {time: new Date().toLocaleTimeString(), sensor:'SYSTEM ERROR', value: errSrc + ': ' + errMsg, level:'ERROR', color:'#d50000'};
return msg;
